  ["Becky Lynch kis desh se hain?","Ireland",["England","Scotland","Wales"],"Becky ka asli naam Rebecca Quin hai aur woh Dublin se hain.","m"],
  ["WrestleMania 2 kitni alag jagahon se ek saath hua tha?","3",["2","4","5"],"Yeh event New York, Chicago aur Los Angeles se hua tha.","h"],
  ["WrestleMania XXX mein Daniel Bryan ne Triple H ke baad kin do wrestlers ko haraakar title jeeta?","Randy Orton aur Batista",["John Cena aur Brock Lesnar","CM Punk aur Roman Reigns","Sheamus aur Alberto Del Rio"],"Bryan ne ek hi raat mein do match jeete.","h"],
  ["CM Punk ki WWE Championship reign (2011-13) kitne din chali?","434 din",["365 din","399 din","478 din"],"Yeh modern era ki sabse lambi WWE Championship reigns mein se ek hai.","h"],
  ["WrestleMania 25 mein Undertaker ne kise haraya?","Shawn Michaels",["Triple H","Edge","Batista"],"Yeh match WrestleMania ke sabse behtareen matches mein gina jata hai.","h"],
  ["Pehla Undisputed WWF Champion kaun bana?","Chris Jericho",["Triple H","The Rock","Stone Cold Steve Austin"],"Jericho ne Vengeance 2001 mein ek hi raat The Rock aur Austin ko haraya.","h"],
  ["WrestleMania X8 (18) kis shehar mein hua tha?","Toronto",["Chicago","Houston","Seattle"],"Yeh event SkyDome mein hua tha.","h"],
  ["Pehla Money in the Bank match (WrestleMania 21) kisne jeeta?","Edge",["Chris Jericho","Chris Benoit","Kane"],"Edge ne baad mein is briefcase se John Cena ke khilaf cash in kiya.","h"],
  ["Ric Flair ka retirement match WrestleMania XXIV mein kis ke khilaf tha?","Shawn Michaels",["Triple H","The Undertaker","John Cena"],"Match ka stipulation tha ki Flair haare to unka career khatam.","h"],
  ["WrestleMania XII mein Shawn Michaels ne apna pehla WWF Championship kise haraakar jeeta?","Bret Hart",["Diesel","The Undertaker","Stone Cold Steve Austin"],"Yeh Iron Man match tha jo sudden death mein khatam hua.","h"],
  ["“Austin 3:16” promo kis wrestler ko haraane ke baad hua tha?","Jake “The Snake” Roberts",["Bret Hart","Ted DiBiase","Vader"],"Yeh King of the Ring 1996 ke final ke baad hua.","h"],
  ["Montreal Screwjob ke baad Bret Hart kis company mein gaye?","WCW",["ECW","TNA","AWA"],"Bret Hart ne 1997 mein WWF chhodkar WCW join ki.","h"],
  ["John Cena ne Royal Rumble 2017 mein kise haraakar apna 16th world title jeeta?","AJ Styles",["Randy Orton","Bray Wyatt","Dean Ambrose"],"Is jeet se Cena ne Ric Flair ke 16 titles ke record ki barabari ki.","h"],
  ["John Cena ne apna aakhri (retirement) match kis ke khilaf khela?","Gunther",["CM Punk","Cody Rhodes","Brock Lesnar"],"Yeh match December 2025 mein Washington DC mein Saturday Night’s Main Event par hua.","h"],
  ["WrestleMania IX mein Hulk Hogan ne kise haraakar WWF title jeeta?","Yokozuna",["Bret Hart","The Undertaker","Lex Luger"],"Yokozuna ne usi raat pehle Bret Hart ko haraya tha, phir Hogan ne title jeeta.","h"],
  ["WrestleMania 22 mein title jeetne ke baad Rey Mysterio ne kise tribute diya?","Eddie Guerrero",["Owen Hart","Andre the Giant","Dusty Rhodes"],"Rey Mysterio ne apne dost Eddie Guerrero ko yaad kiya.","h"],
  ["WrestleMania 39 mein Rhea Ripley ne SmackDown Women’s Champion kise haraya?","Charlotte Flair",["Becky Lynch","Bianca Belair","Asuka"],"Yeh match Los Angeles ke SoFi Stadium mein hua.","h"],
  ["WWE ka pehla United States Champion kaun tha?","Harley Race",["Greg Valentine","Sgt. Slaughter","Roddy Piper"],"Harley Race ne 1 January 1975 ko pehla NWA United States Championship jeeta tha.","h"],
  ["NXT Women's Championship ki pehli champion kaun thi?","Paige",["Emma","Bayley","Sasha Banks"],"Paige ne 24 July 2013 ko Emma ko hara kar inaugural NXT Women's Championship jeeti.","m"],
  ["NXT Tag Team Championship kis saal introduce hui thi?","2013",["2010","2015","2017"],"NXT Tag Team Championship 2013 mein introduce hui thi.","m"],
  ["NXT Women's Tag Team Titles ki pehli champions kaun bani thi?","Dakota Kai aur Raquel Gonzalez",["Ember Moon aur Shotzi Blackheart","Io Shirai aur Zoey Stark","Cora Jade aur Roxanne Perez"],"Dakota Kai aur Raquel Gonzalez inaugural champions bani, lekin usi raat Ember Moon aur Shotzi Blackheart ne titles jeet liye.","h"],
  ["WWE Women's Tag Team Championship ke pehle champions kaun the?","The Boss 'N' Hug Connection",["The IIconics","The Kabuki Warriors","Alexa Bliss aur Nikki Cross"],"Bayley aur Sasha Banks ne 17 February 2019 ko inaugural titles jeete.","h"],
  ["WWE United States Championship ki shuruaat kis promotion mein hui thi?","NWA ke Mid-Atlantic Championship Wrestling mein",["ECW","WWF","TNA"],"Original NWA United States Championship 1 January 1975 ko introduce hui thi.","h"],
  ["WWE mein pehla World Heavyweight Championship 2002 mein kisne present kiya tha?","Eric Bischoff",["Teddy Long","William Regal","John Laurinaitis"],"Raw General Manager Eric Bischoff ne 2 September 2002 ko Triple H ko inaugural champion banaya.","h"],
  ["WWE Championship pehli baar kis wrestler ko diya gaya tha?","Buddy Rogers",["Bruno Sammartino","Pedro Morales","Bob Backlund"],"Buddy Rogers ne 1963 mein tournament final jeetkar inaugural WWE Championship haasil ki.","h"],
  ["WWE mein pehli NXT Women's Champion banne ke liye Paige ne final mein kise haraya tha?","Emma",["Bayley","Natalya","Carmella"],"Paige ne 24 July 2013 ko tournament final mein Emma ko haraya tha.","h"],
  ["WWE ka pehla NXT Champion kaun tha?","Seth Rollins",["Big E","Bo Dallas","Adrian Neville"],"Seth Rollins ne 2012 mein inaugural NXT Championship jeeti thi.","h"],
  ["WWE mein pehli baar Women's United States Championship kisne jeeti?","Chelsea Green",["Zelina Vega","Giulia","Tiffany Stratton"],"Chelsea Green ne 14 December 2024 ko inaugural Women's United States Championship jeeti.","h"],
  ["The New Day ka pehla WWE Tag Team Championship kis saal aaya?","2015",["2013","2014","2017"],"The New Day ne 26 April 2015 ko Extreme Rules mein WWE Tag Team Championship jeeti.","m"],
  ["WWE mein Kofi Kingston ka janm kis desh mein hua tha?","Ghana",["Nigeria","Jamaica","South Africa"],"Kofi Kingston ka janm Ghana mein hua tha.","m"],
  ["WWE Superstar Sami Zayn ka janm kis desh mein hua tha?","Canada",["France","USA","Ireland"],"Sami Zayn ka hometown Montreal, Quebec, Canada hai.","m"],
  ["WWE ka pehla pay-per-view event jo UK mein hua tha kaun sa tha?","SummerSlam 1992",["WrestleMania 17","Survivor Series 1997","King of the Ring 1998"],"SummerSlam 1992 Wembley Stadium, London mein hua tha.","h"],
  ["WWE ke Survivor Series event ka central match concept kya hai?","Elimination tag team match",["Ladder match","Battle royal","Iron Man match"],"Survivor Series traditional elimination tag team matches ke liye jaana jaata hai.","m"],
  ["WrestleMania X mein Bret Hart ko singles match mein kisne haraya tha?","Owen Hart",["Bam Bam Bigelow","Razor Ramon","Earthquake"],"Owen Hart ne WrestleMania X ke opening match mein apne bhai Bret Hart ko haraya tha.","h"],
  ["WrestleMania X ke mixed tag team match mein Bam Bam Bigelow ki partner kaun thi?","Luna Vachon",["Sensational Sherri","Miss Elizabeth","Sunny"],"Bam Bam Bigelow aur Luna Vachon ne Doink aur Dink ko haraya tha.","h"],
  ["WrestleMania X mein Falls Count Anywhere match mein Randy Savage ne kise haraya?","Crush",["Razor Ramon","Adam Bomb","Jeff Jarrett"],"Randy Savage ne Mr. Fuji ke saath aaye Crush ko haraya tha.","h"],
  ["WrestleMania X ke Intercontinental Championship Ladder Match mein Shawn Michaels ko kisne haraya?","Razor Ramon",["Jeff Jarrett","Mr. Perfect","Diesel"],"Razor Ramon ne Shawn Michaels ko hara kar Intercontinental Championship retain ki thi.","h"],
  ["WrestleMania X mein Earthquake ne kis wrestler ko haraya tha?","Adam Bomb",["Crush","Doink","Bam Bam Bigelow"],"Earthquake ne Harvey Wippleman ke saath aaye Adam Bomb ko haraya tha.","h"],
  ["WrestleMania XI ke main event mein NFL legend Lawrence Taylor ne kise haraya tha?","Bam Bam Bigelow",["King Kong Bundy","Bob Backlund","Jeff Jarrett"],"Lawrence Taylor ne WrestleMania XI ke main event mein Bam Bam Bigelow ko haraya tha.","h"],
  ["WrestleMania XI mein Jeff Jarrett ke saath manager ke roop mein kaun tha?","The Roadie",["Jim Cornette","Mr. Fuji","Paul Bearer"],"The Roadie ne Jeff Jarrett ko Razor Ramon ke khilaf Intercontinental Championship match mein accompany kiya tha.","h"],
  ["WrestleMania XI ke I Quit Match mein Bret Hart ne kise haraya?","Bob Backlund",["Diesel","Bam Bam Bigelow","King Kong Bundy"],"Bret Hart ne Roddy Piper ke special guest referee hone par Bob Backlund ko I Quit Match mein haraya tha.","h"],
  ["WrestleMania 21 ke pehle-ever WWE Sumo Match mein Big Show ko kisne haraya?","Akebono",["Yokozuna","The Great Khali","Mark Henry"],"Akebono ne Big Show ko sumo match mein haraya tha.","m"],
  ["WrestleMania 21 mein Women's Championship ke liye Trish Stratus ko kisne challenge kiya tha?","Christy Hemme",["Molly Holly","Ivory","Jazz"],"Trish Stratus ne Christy Hemme ko harakar Women's Championship retain ki thi.","h"],
  ["WrestleMania 21 par Piper's Pit segment ko host karne wale WWE legend kaun the?","Roddy Piper",["Jimmy Snuka","Jesse Ventura","Mean Gene Okerlund"],"Roddy Piper ne WrestleMania 21 par Piper's Pit segment host kiya tha.","m"],
  ["WrestleMania 22 ke Handicap Match mein Booker T aur Sharmell ko kisne haraya?","The Boogeyman",["Finlay","Carlito","Chris Masters"],"The Boogeyman ne WrestleMania 22 mein Booker T aur Sharmell ko haraya tha.","m"],
  ["WrestleMania 22 ke Playboy Pillow Fight mein Candice Michelle ko kisne haraya?","Torrie Wilson",["Maria Kanellis","Trish Stratus","Christy Hemme"],"Torrie Wilson ne WrestleMania 22 ke Playboy Pillow Fight mein Candice Michelle ko haraya tha.","h"],
  ["Survivor Series 2001 mein William Regal ne kis wrestler ko haraya tha?","Tajiri",["Christian","Al Snow","Test"],"William Regal ne Survivor Series 2001 mein Tajiri ko haraya tha.","h"],
  ["Survivor Series 2001 ke Immunity Battle Royal ka winner kaun tha?","Test",["Christian","William Regal","Al Snow"],"Test ne Billy Gunn ko eliminate karke ek saal tak fire hone se immunity jeeti thi.","h"],
  ["Survivor Series 2001 ke winner-takes-all elimination match mein kaunsi team jeeti thi?","Team WWE",["The Alliance","The Un-Americans","The Ministry of Darkness"],"Team WWE ne The Alliance ko harakar storyline mein WWE ka control bachaya tha.","h"],
  ["Pehle SummerSlam ke main event mein special guest referee kaun tha?","Jesse Ventura",["Gorilla Monsoon","Bobby Heenan","Howard Finkel"],"Jesse Ventura ne 1988 ke SummerSlam main event mein special guest referee ki bhoomika nibhayi thi.","h"],
  ["SummerSlam 1988 mein time-limit draw kis tag team match mein hua tha?","The British Bulldogs vs The Fabulous Rougeaus",["Demolition vs The Hart Foundation","The Powers of Pain vs The Bolsheviks","The Rockers vs The Brain Busters"],"British Bulldogs aur Fabulous Rougeaus ka match time-limit draw par khatam hua tha.","h"],
  ["SummerSlam 1988 mein The Hart Foundation ke khilaf World Tag Team Championship kis team ne retain ki?","Demolition",["The British Bulldogs","The Rockers","The Fabulous Rougeaus"],"Demolition ne The Hart Foundation ko harakar World Tag Team Championship retain ki thi.","h"],
  ["WrestleMania 23 ke Battle of the Billionaires match mein Umaga ko kisne haraya?","Bobby Lashley",["Chris Benoit","Mr. Kennedy","The Great Khali"],"Bobby Lashley ne Donald Trump ko represent karte hue Hair vs. Hair match mein Umaga ko haraya tha.","h"],
  ["WrestleMania XXIV ke Belfast Brawl mein Finlay ko kisne haraya?","JBL",["Chavo Guerrero","CM Punk","Batista"],"JBL ne Belfast Brawl mein Finlay ko haraya tha; Hornswoggle bhi Finlay ke saath tha.","h"],
  ["WrestleMania XXIV mein ECW Championship bachane mein kaun nakaam raha?","Chavo Guerrero",["CM Punk","John Morrison","Mark Henry"],"Kane ne Chavo Guerrero ko hara kar ECW Championship jeeti thi.","h"],
  ["SummerSlam 1988 mein Koko B. Ware ko kisne haraya tha?","Big Boss Man",["Bad News Brown","Rick Rude","Dino Bravo"],"Big Boss Man ne pehle SummerSlam event mein Koko B. Ware ko haraya tha.","h"],
  ["WWE ke official profile ke mutabik Razor Ramon ka signature move kya tha?","Razor's Edge",["Perfect-Plex","The Worm","Diving Crossbody"],"WWE ke official profile mein Razor's Edge ko Razor Ramon ka signature move bataya gaya hai.","e"],
  ["Survivor Series 2008 mein Chris Jericho ko hara kar World Heavyweight Championship kisne jeeti?","John Cena",["Batista","Shawn Michaels","Rey Mysterio"],"John Cena ne neck surgery se wapsi ke baad Survivor Series 2008 mein Chris Jericho ko haraya.","h"],
  ["Survivor Series 2008 ke Triple Threat Match mein Triple H aur Vladimir Kozlov ko hara kar WWE Champion kaun bana?","Edge",["Jeff Hardy","The Undertaker","Chris Jericho"],"Edge ne surprise return karke Triple H aur Vladimir Kozlov ko haraya aur WWE Championship jeeti.","h"],
  ["WrestleMania 25 ke Money in the Bank Ladder Match ka winner kaun tha?","CM Punk",["Kofi Kingston","Shelton Benjamin","Christian"],"CM Punk ne WrestleMania 25 mein Money in the Bank Ladder Match jeeta aur lagatar doosri baar yeh match jeetne wale pehle wrestler bane.","h"],
  ["WrestleMania 25 mein Extreme Rules Match mein Jeff Hardy ko kisne haraya?","Matt Hardy",["Edge","CM Punk","Chris Jericho"],"Matt Hardy ne WrestleMania 25 ke Extreme Rules Match mein apne bhai Jeff Hardy ko haraya.","h"],
  ["WrestleMania 25 mein Intercontinental Championship jeetne ke liye Rey Mysterio ne kise haraya?","JBL",["Chris Jericho","John Morrison","MVP"],"Rey Mysterio ne WrestleMania 25 par JBL ko harakar Intercontinental Championship jeeti.","h"],
  ["WrestleMania 26 mein Shawn Michaels ko hara kar apni WrestleMania winning streak 18-0 kisne ki?","The Undertaker",["Triple H","Chris Jericho","Edge"],"The Undertaker ne WrestleMania 26 mein Shawn Michaels ko harakar apni WrestleMania streak 18-0 kar li.","h"],
  ["WrestleMania 26 mein John Cena ne WWE Championship jeetne ke liye kise haraya?","Batista",["Randy Orton","Sheamus","Triple H"],"John Cena ne WrestleMania 26 mein Batista ko hara kar WWE Championship jeeti.","h"],
  ["WrestleMania 26 ke 10-Man Money in the Bank Ladder Match ka winner kaun tha?","Jack Swagger",["Dolph Ziggler","Kofi Kingston","Christian"],"Jack Swagger ne WrestleMania 26 ka 10-Man Money in the Bank Ladder Match jeeta.","h"],
  ["TLC 2010 mein Tables Match jeetkar WWE Championship kisne retain ki?","The Miz",["Randy Orton","John Cena","Wade Barrett"],"The Miz ne TLC 2010 ke Tables Match mein Randy Orton ko hara kar WWE Championship retain ki.","h"],
  ["TLC 2010 ke Fatal 4-Way TLC Match mein World Heavyweight Championship kisne jeeti?","Edge",["Kane","Rey Mysterio","Alberto Del Rio"],"Edge ne Kane, Rey Mysterio aur Alberto Del Rio ko hara kar World Heavyweight Championship jeeti.","h"],
  ["Attitude Era mein WWF ke Monday night show ka naam kya tha?","Raw Is War",["Raw Is Attitude","Nitro Is War","Raw Is Rumble"],"Raw ne 10 March 1997 se 'Raw Is War' naam apnaya. Ye naam 1 October 2001 tak chala.","e"],
  ["Attitude Era mein WWF ko Monday night par takkar dene wala show Nitro kis company ka tha?","WCW (World Championship Wrestling)",["ECW","NWA","AWA"],"WCW Nitro aur WWF Raw ke beech ratings ki ladai ko Monday Night War kaha gaya.","e"],
  ["Attitude Era mein 'Mr. McMahon' ka villain character kaun nibhata tha?","Vince McMahon",["Shane McMahon","Paul Heyman","Triple H"],"Montreal Screwjob ke baad Vince McMahon ne khud ka bossy aur villain wala 'Mr. McMahon' character banaya.","e"],
  ["WrestleMania XIV mein Austin aur Shawn Michaels ke match mein Mike Tyson ka kya role tha?","Special ringside enforcer",["Special guest referee","Commentator","Timekeeper"],"Mike Tyson ne ringside enforcer ban kar Austin ko jeetne mein madad ki. Austin ne WWF Championship jeeti.","e"],
  ["WrestleMania XV (1999) ke main event mein Stone Cold Steve Austin ke saamne kaun tha?","The Rock",["Triple H","Mankind","Big Show"],"WM XV mein Austin ne The Rock ko no disqualification match mein haraya. Mankind special guest referee the.","e"],
  ["WrestleMania X-Seven (2001) kis stadium mein hua tha?","Reliant Astrodome (Houston)",["Pontiac Silverdome","Georgia Dome","SkyDome"],"WrestleMania X-Seven Houston ke Astrodome mein hua tha. Isme Austin ne The Rock ko haraakar WWF Championship jeeti.","e"],
  ["WrestleMania X8 (2002) ke main event mein Triple H ne kise haraakar Undisputed Championship jeeti?","Chris Jericho",["The Rock","Stone Cold Steve Austin","Kurt Angle"],"WM X8 Toronto ke SkyDome mein hua tha. Triple H ne Jericho ko haraakar Undisputed Champion ka khitaab jeeta.","e"],
  ["WrestleMania XIX (2003) mein Brock Lesnar ne kise haraakar WWE Championship jeeti?","Kurt Angle",["The Rock","Big Show","The Undertaker"],"WM XIX Seattle ke Safeco Field mein hua tha. Lesnar ne Kurt Angle ko haraakar pehli baar WrestleMania mein title jeeta.","e"],
  ["WrestleMania 21 (2005) ke main event mein Batista ne kise haraakar World Heavyweight Championship jeeti?","Triple H",["John Cena","Randy Orton","Shawn Michaels"],"WM 21 Los Angeles ke Staples Center mein hua tha. Batista ne Triple H ko haraakar apna pehla World title jeeta.","e"],
  ["WrestleMania 22 (2006) ke main event mein John Cena ne kise haraakar WWE Championship retain ki?","Triple H",["Shawn Michaels","Edge","Randy Orton"],"WM 22 Rosemont ke Allstate Arena mein hua tha. Cena ne Triple H ko haraakar title bachayi.","e"],
  ["WrestleMania 29 (2013) mein John Cena ne kise haraakar WWE Championship jeeti?","The Rock",["CM Punk","Randy Orton","Brock Lesnar"],"WM 29 MetLife Stadium (New Jersey) mein hua tha. Cena ne The Rock se 'Once in a Lifetime' ka badla liya.","e"],
  ["SummerSlam 2002 mein The Rock se Undisputed Championship kisne jeeti?","Brock Lesnar",["Kurt Angle","Triple H","The Undertaker"],"Brock Lesnar ne Uniondale ke Nassau Coliseum mein The Rock ko haraakar apna pehla WWE title jeeta.","e"],
  ["SummerSlam 2008 ke Hell in a Cell main event mein Edge ko kisne haraya?","The Undertaker",["John Cena","Batista","CM Punk"],"SummerSlam 2008 Indianapolis mein hua tha. Undertaker ne Edge ko Hell in a Cell mein haraya.","e"],
  ["SummerSlam 2014 mein Brock Lesnar ne kise haraakar WWE World Heavyweight Championship jeeti?","John Cena",["Roman Reigns","Randy Orton","Dean Ambrose"],"Lesnar ne Cena ko bure tareeke se haraya aur ye match 'Suplex City' ke liye mashhoor hua.","e"],
  ["SummerSlam 2021 (Las Vegas) ke main event mein Roman Reigns ne kise haraya?","John Cena",["Brock Lesnar","Seth Rollins","Kevin Owens"],"SummerSlam 2021 Allegiant Stadium (Las Vegas) mein hua. Reigns ne Cena ko haraakar Universal Championship bachayi.","e"],
  ["SummerSlam 2022 ke Last Man Standing match mein Roman Reigns ne kise haraya?","Brock Lesnar",["Drew McIntyre","Seth Rollins","Cody Rhodes"],"SummerSlam 2022 Nashville mein hua. Reigns ne Lesnar ko Last Man Standing match mein haraya.","e"],
  ["Stone Cold Steve Austin ne WrestleMania XIV mein jeeta hua WWF Championship kis shehar mein jeeta?","Boston",["New York","Chicago","Houston"],"WrestleMania XIV 29 March 1998 ko Boston ke FleetCenter mein hua tha.","e"],
  ["Mankind ne apna pehla WWF Championship (Dec 1998) kise haraakar jeeta?","The Rock",["Stone Cold Steve Austin","Triple H","The Undertaker"],"Mankind ne 29 December 1998 ko Raw par The Rock ko haraakar apna pehla WWF title jeeta (episode 4 January 1999 ko aaya).","e"],
  ["'WWF Attitude' ka scratch logo pehli baar kis event par dikhaya gaya?","Survivor Series 1997",["WrestleMania XIV","Royal Rumble 1998","SummerSlam 1997"],"9 November 1997 ko Survivor Series (Montreal Screwjob wala event) par ye logo pehli baar dikhaya gaya. Aksar isi se Attitude Era ki shuruaat maani jati hai.","m"],
  ["Monday Night War kis taareekh ko khatam hui (WCW ke khareed jaane par)?","26 March 2001",["4 September 1995","6 May 2002","1 April 2001"],"26 March 2001 ko Vince McMahon ne Raw aur Nitro ke simulcast mein WCW ko khareedne ka elaan kiya.","m"],
  ["WWF ne WCW ko kis company se khareeda tha?","AOL Time Warner",["Viacom","Sony","Disney"],"AOL Time Warner ne WCW ke assets March 2001 mein WWF ko bech diye.","m"],
  ["Raw Is War ka naam kab hata kar sirf 'Raw' rakha gaya?","1 October 2001",["10 March 1997","26 March 2001","6 May 2002"],"Raw Is War naam 1 October 2001 ko retire hua.","m"],
  ["Raw ne 'Raw Is War' naam kis taareekh se apnaya?","10 March 1997",["9 November 1997","1 October 2001","13 April 1998"],"10 March 1997 ko WWF ne Raw ko 'Raw Is War' naam diya, taaki WCW ke saath 'war' ka mahaul bane.","m"],
  ["13 April 1998 ki Raw (Austin vs Mr. McMahon) kis wajah se mashhoor hai?","Raw ne 84 hafton baad pehli baar Nitro ko ratings mein haraya",["Austin ne Raw par pehli baar WWF title jeeta","Montreal Screwjob isi din hua","Raw ka naam Raw Is War hua"],"Is episode ke baad WWF ne Monday Night War mein WCW par badhat bana li.","m"],
  ["SummerSlam 1999 ke Triple Threat match mein Mankind ne kiska WWF Championship chheena?","Stone Cold Steve Austin",["The Rock","Triple H","Big Show"],"Mankind ne SummerSlam 1999 mein Austin (champion) aur Triple H ko haraakar title jeeta. Jesse Ventura special guest referee the.","m"],
  ["Triple H ne apna pehla WWF Championship August 1999 mein kise haraakar jeeta?","Mankind",["Stone Cold Steve Austin","The Rock","Big Show"],"Triple H ne 23 August 1999 ko Raw par Mankind ko haraakar pehla WWF title jeeta.","m"],
  ["Kane ne June 1998 mein King of the Ring par WWF Championship kisse jeeti?","Stone Cold Steve Austin",["The Rock","Mankind","Triple H"],"Kane ne 28 June 1998 ko Austin se WWF title jeeta tha.","m"],
  ["King of the Ring 2000 ke six-man tag match mein The Rock ne kise pin karke Triple H ka title jeeta?","Vince McMahon",["Shane McMahon","Triple H","Kane"],"25 June 2000 ko The Rock ne Vince McMahon ko pin karke WWF Championship jeeti.","m"],
  ["Unforgiven 2001 mein Kurt Angle ne kisse WWF Championship chheeni?","Stone Cold Steve Austin",["The Rock","Chris Jericho","The Undertaker"],"Angle ne 23 September 2001 ko Austin ki 175 din ki reign khatam ki.","m"],
  ["Chris Jericho ne Vengeance 2001 mein ek hi raat mein kin do ko haraakar pehla Undisputed WWF Champion bana?","The Rock aur Stone Cold Steve Austin",["Kurt Angle aur Triple H","Kane aur The Undertaker","Booker T aur Edge"],"9 December 2001 ko Jericho ne The Rock aur Austin ko ek hi raat mein haraakar WWF aur WCW titles ko ek kar diya.","m"],
  ["Backlash 2002 mein Triple H se Undisputed Championship kisne jeeti?","Hulk Hogan",["The Undertaker","The Rock","Kurt Angle"],"Hulk Hogan ne Backlash 2002 mein Triple H ko haraakar Undisputed title jeeta.","m"],
  ["Judgment Day 2002 (19 May) mein Hulk Hogan se Undisputed Championship kisne jeeti?","The Undertaker",["Triple H","The Rock","Kurt Angle"],"Undertaker ne Hogan ko haraakar title jeeta aur 63 din tak champion rahe.","m"],
  ["Vengeance 2002 ke Triple Threat mein The Rock ne kise pin karke apna 7th WWF/WWE title jeeta?","Kurt Angle",["The Undertaker","Triple H","Brock Lesnar"],"21 July 2002 ko The Rock ne Kurt Angle ko pin kiya aur Undertaker se title jeeta. Ye unki record 7th title reign thi.","m"],
  ["SummerSlam 2000 mein pehli baar kaun sa match type hua?","TLC (Tables, Ladders & Chairs)",["Elimination Chamber","Money in the Bank","Royal Rumble"],"SummerSlam 2000 Raleigh mein hua tha. Pehla TLC match Edge & Christian, The Hardy Boyz aur The Dudley Boyz ke beech hua.","m"],
  ["SummerSlam 2001 ke main event mein The Rock ne kise haraakar WCW Championship jeeti?","Booker T",["Stone Cold Steve Austin","Kurt Angle","Triple H"],"SummerSlam 2001 San Jose mein hua. Ye Invasion storyline ka hissa tha.","m"],
  ["SummerSlam 2003 ka main event kis match type ka tha?","Elimination Chamber",["Hell in a Cell","Ladder Match","Triple Threat"],"Triple H ne SummerSlam 2003 (Phoenix) mein Elimination Chamber match jeetkar World Heavyweight Championship retain ki.","m"],
  ["SummerSlam 2004 mein Randy Orton kitni umar mein World Heavyweight Champion bane (youngest ever)?","24 saal",["22 saal","25 saal","27 saal"],"Orton ne Chris Benoit ko Toronto mein haraakar youngest World Heavyweight Champion ka record banaya.","h"],
  ["Randy Orton ki pehli World Heavyweight Championship reign (SummerSlam 2004) kitne din chali?","28 din",["14 din","60 din","85 din"],"Triple H ne 12 September 2004 ko Unforgiven mein Orton se title wapas le liya.","h"],
  ["Mankind ne apna pehla WWF Championship reign kis taareekh ko jeeta (Worcester ki Raw)?","29 December 1998",["15 November 1998","23 August 1999","28 June 1998"],"Mankind ne The Rock ko haraya. Episode 4 January 1999 ko aired hua.","h"],
  ["WrestleMania XIX (2003) kis stadium mein hua tha?","Safeco Field (Seattle)",["Reliant Stadium (Houston)","SkyDome (Toronto)","Pontiac Silverdome"],"WM XIX mein Brock Lesnar ne Kurt Angle ko haraakar WWE Championship jeeti.","h"],
  ["WrestleMania XX (2004) kis jagah hua tha?","Madison Square Garden (New York)",["Staples Center (Los Angeles)","Allstate Arena (Rosemont)","Ford Field (Detroit)"],"WM XX main event mein Chris Benoit ne Triple H aur Shawn Michaels ko haraakar World Heavyweight Championship jeeti.","h"],
  ["WrestleMania 32 (2016) ka claimed attendance kitna tha (single night ka WrestleMania record)?","101,763",["93,173","80,676","82,265"],"WM 32 AT&T Stadium (Arlington, Texas) mein hua tha. Roman Reigns ne Triple H ko haraakar title jeeta.","h"],
  ["WrestleMania 37 (2021) kis stadium mein hua tha?","Raymond James Stadium (Tampa)",["SoFi Stadium","AT&T Stadium","Mercedes-Benz Stadium"],"WM 37 do raat (10-11 April 2021) mein Tampa mein hua. Night 2 mein Roman Reigns ne Bryan aur Edge ko haraya.","h"],
  ["WrestleMania 36 (2020) kahan hua, jahan koi live crowd nahi thi?","WWE Performance Center (Orlando)",["Madison Square Garden","Raymond James Stadium","Mercedes-Benz Stadium"],"WM 36 do raat (4-5 April 2020) mein bina live fans ke hua. Night 1 mein Undertaker ne Boneyard match jeeta.","h"],
  ["WrestleMania 36 ke Night 2 main event mein Drew McIntyre ne kise haraakar WWE Championship jeeti?","Brock Lesnar",["Roman Reigns","Randy Orton","AJ Styles"],"McIntyre ne WM 36 Night 2 mein Lesnar ko haraakar apni pehli WWE Championship jeeti.","h"],
  ["WrestleMania 37 Night 1 ke main event mein SmackDown Women's Championship kisne jeeti?","Bianca Belair",["Sasha Banks","Becky Lynch","Charlotte Flair"],"Bianca Belair ne Sasha Banks ko haraakar SmackDown Women's Championship jeeti.","h"],
  ["SummerSlam 2020 mein 'The Fiend' Bray Wyatt ne Universal Championship kisse jeeti?","Braun Strowman",["Roman Reigns","Seth Rollins","Brock Lesnar"],"Falls Count Anywhere match mein The Fiend ne Strowman ko haraakar Universal Championship jeeti.","h"],
  ["SummerSlam 2019 mein Universal Champion Brock Lesnar ko kisne haraya?","Seth Rollins",["Roman Reigns","Braun Strowman","Bray Wyatt"],"SummerSlam 2019 Toronto mein hua tha. Rollins ne Lesnar ko haraakar Universal Championship jeeti.","h"],
  ["SummerSlam 2023 ke Tribal Combat match mein Roman Reigns ne kise haraya?","Jey Uso",["Jimmy Uso","Solo Sikoa","Cody Rhodes"],"SummerSlam 2023 Detroit mein hua. Jimmy Uso ke betrayal ke baad Reigns jeeta.","h"],
  ["SummerSlam 2005 ke main event mein Hulk Hogan ne kise haraya?","Shawn Michaels",["Triple H","Randy Orton","Batista"],"SummerSlam 2005 Washington, D.C. mein hua. Hogan ne Shawn Michaels ko haraya.","h"]
